// Current language
let currentLang = localStorage.getItem('dragonStory_lang') || 'en';

// Toggle language
function toggleLanguage() {
  currentLang = currentLang === 'en' ? 'fr' : 'en';
  localStorage.setItem('dragonStory_lang', currentLang);
  applyLanguage();
}

// Apply language to current page
function applyLanguage() {
  const texts = Translations[currentLang];

  // Update all elements with data-i18n attribute
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (texts[key]) {
      el.innerHTML = texts[key];
    }
  });

  // Update language button
  const langBtn = document.getElementById('langToggle');
  if (langBtn) {
    langBtn.textContent = texts.langButton;
  }

  // Update page title based on data attribute
  const pageTitle = document.querySelector('[data-i18n-page-title]');
  if (pageTitle && texts[pageTitle.getAttribute('data-i18n-page-title')]) {
    document.title = texts[pageTitle.getAttribute('data-i18n-page-title')];
  }
}

// Translate a single key, with optional {placeholder} interpolation
// Used by the boss fight, where text is generated by JavaScript
function t(key, vars) {
  const dict = Translations[currentLang] || Translations.en;
  let text = (dict[key] !== undefined) ? dict[key]
         : (Translations.en[key] !== undefined ? Translations.en[key] : key);
  if (vars) {
    text = text.replace(/\{(\w+)\}/g, (match, name) =>
      (vars[name] !== undefined ? vars[name] : match)
    );
  }
  return text;
}

// Initialize language on page load
document.addEventListener('DOMContentLoaded', function() {
  applyLanguage();
});
